-- Rosewood palette loader.
--
-- The colors are generated by the rosewood CLI into
--   $XDG_CONFIG_HOME/rosewood/generated/nvim-palette.lua
-- When that file is missing, the locked defaults below are used.

local M = {
  flavor  = "dark",
  bg      = "#0E0A0D",
  bg_soft = "#1A1418",
  bg_alt  = "#2A2028",
  bg_sel  = "#3A2E35",
  fg      = "#F2D5C4",
  muted   = "#5C4A52",
  none    = "NONE",

  -- the three accents
  rose  = "#C77D9A",
  steel = "#6A8A9A",
  red   = "#D9534F",
}

local conf = vim.env.XDG_CONFIG_HOME or vim.fn.expand("~/.config")
local generated = conf .. "/rosewood/generated/nvim-palette.lua"

local f = io.open(generated, "r")
if f then
  f:close()
  local ok, loaded = pcall(dofile, generated)
  if ok and type(loaded) == "table" then
    M = loaded
  end
end

return M
